export default function (input) {
  const e = input.event || {};
  const d = e.data || {};
  const kinds = { PURCHASE: 'card purchase', CARD_PURCHASE: 'card purchase', TRANSFER: 'transfer to terminal', CARD_TRANSFER: 'card transfer',
    WITHDRAWAL: 'withdrawal', BILL_PAYMENT: 'bill payment', COLLECTION: 'collection', PAY_CODE: 'pay code', AIRTIME: 'airtime', BOOM: 'boom' };
  const short = String(e.eventType || '').replace(/^V1_/, '').replace(/_TRANSACTION$/, '').replace(/^POS_/, '');
  const kind = kinds[short] || (d.transactionType ? String(d.transactionType).toLowerCase().replace(/_/g, ' ') : 'other');
  const status = String(d.transactionStatus || '').toUpperCase();
  const approved = ['COMPLETED', 'APPROVED', 'SUCCESS', 'SUCCESSFUL'].indexOf(status) >= 0;
  const pending = status === 'PENDING' || status === '';
  const kobo = Number(d.amount);
  const amount = isFinite(kobo) ? Math.round(kobo) / 100 : 0;
  let when = null;
  const t = String(d.transactionTime || '');
  if (/^\d{4}\/\d{2}\/\d{2} \d{2}:\d{2}:\d{2}$/.test(t)) when = new Date(t.replace(/\//g, '-').replace(' ', 'T') + '+01:00');
  else if (t) when = new Date(t);
  if (!when || isNaN(when.getTime())) when = new Date(input.received_at);
  if (isNaN(when.getTime())) when = new Date(0);
  const lagos = new Date(when.getTime() + 3600 * 1000);
  let customer = '';
  try { const m = JSON.parse(d.metaData || '{}'); customer = String((m && m.customerName) || ''); } catch (err) { customer = ''; }
  return { row: {
    reference: String(d.transactionReference || e.eventId || ''), terminal: String(d.terminalSerial || ''), kind: kind,
    status: status ? status.toLowerCase() : 'unknown', approved: approved, amount: amount, happened_at: when.toISOString(),
    sale_date: lagos.toISOString().slice(0, 10), customer: customer, narration: String(d.narration || ''),
    response: String(d.responseMessage || ''), event: String(e.eventType || '') }, pending: pending, naira: amount };
}
